var i=[{title:`Μέρη της μπάρας`,text:`Μια τυπική διάταξη έχει μια μπάρα, δίσκους που ταιριάζουν σε αυτή και σφιγκτήρες (collars) για να κρατούν τους δίσκους στη θέση τους όταν χρειάζεται. Η άδεια μπάρα μπορεί να φαίνεται βαριά σε έναν αρχάριο, και οι ειδικές μπάρες έχουν διαφορετικά βάρη και μεγέθη. Καταγράψτε το συνολικό βάρος που σηκώνετε, μαζί με τη μπάρα, και όχι μόνο τους δίσκους.`},{title:`Γιατί να χρησιμοποιήσετε μπάρα`,text:`Οι μικροί δίσκοι σας επιτρέπουν να προσθέτετε φορτίο σε ακριβή βήματα, και μία μπάρα μπορεί να προπονήσει αρκετά μεγάλα κινητικά πρότυπα. Και τα δύο χέρια κρατούν μία συνδεδεμένη μπάρα, όμως, και αυτό δεν ταιριάζει σε κάθε ώμο ή καρπό. Οι αλτήρες, τα μηχανήματα ή οι ασκήσεις με το σωματικό βάρος μπορεί να είναι καλύτερη επιλογή όταν ο εξοπλισμός, η άνεση ή η εμπειρία σας είναι περιορισμένα.`},{title:`Ρύθμιση ράφι και ασφάλειας`,text:`Για καθισιές, ρυθμίστε τα J-hooks στο σωστό ύψος για εσάς, και τοποθετήστε τους βραχίονες ή τους πείρους ασφαλείας εκεί όπου θα πιάσουν μια αποτυχημένη επανάληψη ενώ σας αφήνουν να κινηθείτε σε ολόκληρο το προγραμματισμένο εύρος. Για την πίεση πάγκου, χρησιμοποιήστε ικανό βοηθό (spotter) ή ασφάλειες που έχουν ρυθμιστεί σωστά. Εξασκηθείτε στο να μπαίνετε και να βγαίνετε από το ράφι με άδεια μπάρα πριν σηκώσετε δύσκολα φορτία.`},{title:`Μάθετε πριν φορτώσετε`,text:`Εξασκηθείτε στην καθισιά, στην άρθρωση ισχίου, στην πίεση ή στην κωπηλασία με ελαφριά αντίσταση μέχρι η μπάρα να ακολουθεί την ίδια διαδρομή σε κάθε επανάληψη. Ασφαλίστε τους δίσκους όταν χρειάζεται, ελέγξτε τον χώρο γύρω σας, και μην υποθέτετε ποτέ ότι ένας πάγκος, μια βάση ή ένα αυτοσχέδιο ράφι μπορεί να πιάσει μια πέφτουσα μπάρα. Δεν χρειάζεται να δοκιμάσετε το μέγιστο μίας επανάληψής σας για να χτίσετε δύναμη ως αρχάριος. Κάντε ασκήσεις με μπάρα μόνο όταν έχετε τη σωστή μπάρα και δίσκους, ένα ράφι ή άλλη ασφαλή διάταξη και αρκετό χώρο. Αν προπονείστε μόνοι χωρίς κατάλληλες ασφάλειες ή έχετε περιορισμούς στη φόρτιση της σπονδυλικής σας στήλης, διαλέξτε άλλη άσκηση.`}];var l=[{label:`NSCA: ασφάλεια και βασικές αρχές της προπόνησης με αντίσταση`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Mayo Clinic: τεχνική προπόνησης με βάρη (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`Θέση του ACSM για το 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var s={sections:i,sources:l};export{s as default,i as sections,l as sources};